package portfolio.week08;
import javafx.application.Application; import javafx.beans.property.SimpleIntegerProperty; import javafx.beans.property.SimpleStringProperty; import javafx.scene.Scene; import javafx.scene.control.*; import javafx.scene.layout.VBox; import javafx.stage.Stage;
public final class ListenerDemo extends Application { public void start(Stage s){SimpleStringProperty name=new SimpleStringProperty("Initial");SimpleIntegerProperty count=new SimpleIntegerProperty(0);name.addListener((obs,oldValue,newValue)->count.set(count.get()+1));TextField input=new TextField();input.textProperty().bindBidirectional(name);Label status=new Label();status.textProperty().bind(name.concat(" — changes: ").concat(count.asString()));VBox box=new VBox(10,input,status);box.setPadding(new javafx.geometry.Insets(18));s.setScene(new Scene(box,420,150));s.show();}public static void main(String[]a){launch(a);}}
